   {rule.id==='open-hall-workspace'&&<div className="flex flex-wrap items-center gap-2"><label>Copy across divider <select aria-label="Duplicate mirror plane" value={duplicateAxis} onChange={e=>setDuplicateAxis(Number(e.target.value) as 0|1)} className="rounded border p-1" style={style}><option value={0}>YZ · X divider</option><option value={1}>XZ · Y divider</option></select></label><button disabled={busy||stale||!editSelection.length||editorBase.length+editSelection.length>240} onClick={duplicateSelected} className="rounded border px-3 py-1 disabled:opacity-40" style={button()}>Duplicate + mirror selected</button><button disabled={busy||!editSelection.some(i=>i>=editBase.length)} onClick={deleteSelectedCopies} className="rounded border px-3 py-1 disabled:opacity-40" style={button()}>Delete selected copies</button><span>{editDuplicates.filter(c=>!c.deleted).length} added copies</span></div>}
   <div className="flex max-h-48 flex-wrap gap-2 overflow-auto">{editorBase.map((p,i)=>i>=editBase.length&&editDuplicates[i-editBase.length]?.deleted?null:<label key={i} className="flex items-center gap-1 rounded border p-2" style={button(editSelection.includes(i))}><input aria-label={`Select letter ${i+1}`} type="checkbox" checked={editSelection.includes(i)} onChange={e=>setEditSelection(ids=>e.target.checked?[...ids,i]:ids.filter(id=>id!==i))}/>{p.letter} {i+1}{i>=editBase.length?' copy':''}{i>=editBase.length&&<button type="button" aria-label={`Delete copy ${p.letter}${i+1}`} disabled={busy} onClick={e=>{e.preventDefault();deleteCopy(i);}} className="rounded border px-1" style={button()}>Delete</button>}</label>)}</div>
