  <div className="flex flex-wrap gap-2 border-t pt-3 text-xs" style={{borderColor:"var(--line)"}}><button disabled={!selected?.indices.length||stale||busy} onClick={()=>selected&&download(`${rule.id}-${effectiveMode}.obj`,obj(stage===9?aggregateMesh:selected))} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Export {stage===9?"aggregation":"selected variation"} OBJ</button><button disabled={stage===-2||stage>=10||busy||stale} onClick={exportPng} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Current view PNG</button><button disabled={!selected?.indices.length||stale||busy||exporting} onClick={()=>void exportSheet()} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>{exporting?"Preparing PDF…":"Export plan + section + iso · 33 × 12.5 in PDF"}</button><button disabled={!selected?.indices.length||stale||busy||exporting} onClick={()=>{if(!selected)return;setExporting(true);setExportError("");setBoardMessage("");void exportGeneratorSheet(selected,rule.name,((data?.gatheringOperations||data?.officeValidation)&&effectiveMode==="letters"?"Variation A — Intersecting letters":names[effectiveMode])+" | "+(snapshot?.label??""),effectiveMode==="voids","board",data?.enclosure,iso).then(blob=>savePresentationGraphic(rule.id,rule.name,blob,"geometry")).then(()=>setBoardMessage("Geometry sent to Presentation.")).catch(error=>setExportError(error instanceof Error?error.message:"Could not send geometry to the board.")).finally(()=>setExporting(false));}} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>{exporting?"Preparing board…":"Download Geometry Board"}</button><button disabled={!snapshot||stale||busy} onClick={()=>download(`${rule.id}-workflow.json`,JSON.stringify({schema:2,units:"feet",snapshot:{...snapshot,data},moduleRange,canonicalData:snapshot?.data,preferred,rationale,descriptors:props.descriptors},null,2))} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Workflow + evaluation JSON</button><button disabled={!data?.formation||stale||busy} onClick={()=>{const root=document.getElementById('generated-rules-export');if(root)void exportRulesExcel(root,rule.id).catch(error=>setExportError(error instanceof Error?error.message:'Could not export Excel file.'));}} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Export Rules Excel</button><button disabled={!data?.formation||stale||busy} onClick={()=>{try{setExportError('');const root=document.getElementById('generated-rules-export');if(!root)return;const bounds=root.getBoundingClientRect(),width=Math.ceil(root.scrollWidth),height=Math.ceil(root.scrollHeight),scale=Math.min(2,16000/Math.max(width,height));const canvas=document.createElement('canvas');canvas.width=Math.ceil(width*scale);canvas.height=Math.ceil(height*scale);const ctx=canvas.getContext('2d');if(!ctx)throw new Error('Could not create the rules image.');ctx.scale(scale,scale);ctx.fillStyle='#080d12';ctx.fillRect(0,0,width,height);for(const element of [root,...Array.from(root.querySelectorAll('*'))]){const style=getComputedStyle(element),rect=element.getBoundingClientRect(),x=rect.left-bounds.left+root.scrollLeft,y=rect.top-bounds.top+root.scrollTop;if(style.backgroundColor!=='rgba(0, 0, 0, 0)'&&style.backgroundColor!=='transparent'){ctx.fillStyle=style.backgroundColor;ctx.fillRect(x,y,rect.width,rect.height);}for(const side of ['top','right','bottom','left'] as const){const size=parseFloat(style.getPropertyValue('border-'+side+'-width'));if(!size||style.getPropertyValue('border-'+side+'-style')==='none')continue;ctx.fillStyle=style.getPropertyValue('border-'+side+'-color');if(side==='top')ctx.fillRect(x,y,rect.width,size);if(side==='bottom')ctx.fillRect(x,y+rect.height-size,rect.width,size);if(side==='left')ctx.fillRect(x,y,size,rect.height);if(side==='right')ctx.fillRect(x+rect.width-size,y,size,rect.height);}}const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node:Node|null;while((node=walker.nextNode())){const parent=node.parentElement,text=node.textContent||'';if(!parent||!text.trim())continue;const style=getComputedStyle(parent);if(style.display==='none'||style.visibility==='hidden')continue;ctx.fillStyle=style.color;ctx.font=style.fontStyle+' '+style.fontWeight+' '+style.fontSize+' '+style.fontFamily;ctx.textBaseline='top';for(const match of text.matchAll(/\S+/g)){const range=document.createRange();range.setStart(node,match.index!);range.setEnd(node,match.index!+match[0].length);const rect=range.getBoundingClientRect();ctx.fillText(match[0],rect.left-bounds.left+root.scrollLeft,rect.top-bounds.top+root.scrollTop);range.detach();}}canvas.toBlob(blob=>{if(!blob){setExportError('Could not create the rules image.');return;}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`${rule.id}-rules.png`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');}catch(error){setExportError(error instanceof Error?error.message:'Could not create the rules image.');}}} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Export Rules PNG</button><button disabled={!data?.formation||stale||busy} onClick={()=>{if(data)void exportGraphicRules(data,rule.name,rule.id,bridgePreview.lines,thickness,placements(source)).catch(error=>setExportError(error instanceof Error?error.message:"Could not export graphic rules."));}} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Download Graphic Rules</button><button disabled={!data?.formation||stale||busy||exporting} onClick={()=>{if(!data)return;setExporting(true);setExportError("");setBoardMessage("");void createGraphicRules(data,rule.name,bridgePreview.lines,thickness,placements(source),committedEditor.current??undefined).then(blob=>savePresentationGraphic(rule.id,rule.name,blob)).then(()=>setBoardMessage("Graphic sent to Presentation.")).catch(error=>setExportError(error instanceof Error?error.message:"Could not send graphic to the board.")).finally(()=>setExporting(false));}} className="rounded border px-2 py-1 disabled:opacity-40" style={button()}>Download Graphic Rules to Board</button></div>
  {boardMessage&&<p role="status" className="text-xs" style={{color:"var(--accent-light)"}}>{boardMessage}</p>}
  {exportError&&<p role="alert" className="text-xs text-red-300">{exportError}</p>}
  <p className="text-[10px]" style={{color:"var(--muted)"}}>OBJ coordinates retain the feet and Z-up orientation. White models, comparison, measurements and exports all use the same A/B/C meshes.</p>
